let optarif = {
	'BASE': 'Option Base',
	'HC..': 'Option Heures Creuses',
	'EJP.': 'Option Effacement Jour de Pointe',
	'BBR.': 'Option Tempo'
}

let ptec = {
	'TH..': "Toutes les Heures",
	'HC..': "Heures Creuses",
	'HP..': "Heures Pleines",
	'HN..': "Heures Normales",
	'PM..': "Heures de Pointe Mobile",
	'HCJB': "Heures Creuses Jours Bleus",
	'HCJW': "Heures Creuses Jours Blancs",
	'HCJR': "Heures Creuses Jours Rouges",
	'HPJB': "Heures Pleines Jours Bleus",
	'HPJW': "Heures Pleines Jours Blancs",
	'HPJR': "Heures Pleines Jours Rouges"
}

let names = {
	'ADCO': 'Addresse de compteur',
	'OPTARIF': 'Option tarifaire',
	'ISOUSC': 'Intensité souscrite',
	'BASE': 'Index de base',
	'HCHC': 'Heures creuses',
	'HCHP': 'Heures pleines',
	'EJPHN': 'Heures normales',
	'EJPHPM': 'Heures de point mobile',
	'BBRHCJB': 'Heures creuses jours bleus',
	'BBRHPJB': 'Herues pleines jours bleus',
	'BBRHCJW': 'Heures creuses jours blancs',
	'BBRHPJW': 'Heures peines jours blancs',
	'BBRHCJR': 'Heures creuses jours rouges',
	'BBRHPJR': 'Heures pleines jours rouges',
	'PEJP': 'Préavis debuté EJP',
	'PTEC': 'Période tarifaire en cours',
	'DEMAIN': 'Couleur du lendemain',
	'IINST': 'Intensité instantanée',
	'PAPP': 'Puissance apparente',
	'HHPHC': 'Groupe horaire'
}

// Remove dirty code
var lines = msg.payload.toString().replace("\u0002\n","").replace("\r\u0003","");
msg.payload = {};

// Split message by line
lines = lines.split("\r\n");
for (var line in lines) {

	// Prepare checksum
	let i;
	let checksum = 32;
	let myline = lines[line].toString().replace("  "," s").split(" ");

	// Split current message
	let check = myline.pop();
	let value = myline.pop();
	let label = myline.pop();

	// Regain checksum
	if (check == "s") check = " ";

	// Calcul checksum
	for (i = 0; i < label.length; i++) checksum += label.charCodeAt(i);
	for (i = 0; i < value.length; i++) checksum += value.charCodeAt(i);
	checksum = ((checksum%256) & 63) + 32;
	checksum = String.fromCharCode(checksum);

	// Checksum is not ok
	if (checksum != check ) {
		let error = {
			'topic':'',
			'payload': 'Bad Checksum "' + checksum + '" for label "' + label + '".'
		};
		return [null, error];
	}

	// Parse message
	let full = value;
	let trans = value;
	let name = label;

	// get readbale label
	if (typeof names[label] == 'string') {
		name = names[label];
	}

	// Convert numeric value to number
	if (!isNaN(trans) && isFinite(Number(trans))) trans = Number(trans);

	// OPTARIF : chars, length 4
	if (label == "OPTARIF") {
		if (trans.substring(trans.length - 1) == '.') trans = trans.substring(0, trans.length -1);
		if (trans.substring(trans.length - 1) == '.') trans = trans.substring(0, trans.length -1);

		full = typeof optarif[value] === 'string' ? optarif[value] : '';
	}
	// HHPHC : char, length 1
	else if (label == "HHPHC") {
		//trans = full = value.charCodeAt();
	}
	// PTEC : chars, length 4
	else if (label == "PTEC") {

		if (trans.substring(trans.length - 1) == '.') trans = trans.substring(0, trans.length -1);
		if (trans.substring(trans.length - 1) == '.') trans = trans.substring(0, trans.length -1);

		full = typeof ptec[value] === 'string' ? ptec[value] : '';
	}

	// Add to output
	msg.payload[label] ={
		'raw': value,
		'value': trans,
		'full': full,
		'name': name
	};
}

return [msg, null];

